document.addEventListener("DOMContentLoaded",(()=>{"use strict";class UbuntuDevSpace{constructor(){this.html=document.documentElement;this.body=document.body;this.currentDomain=window.location.hostname}async fetchClientData(){try{const response=await fetch("https://cdn.jsdelivr.net/gh/OumaNyang/ubuntu-devspace-js@main/data/clients.data.json");const devData=await response.json();this.handleLicenseStatus(devData)}catch(error){console.error("Failed to load client data:",error)}}handleLicenseStatus(devData){const domainData=devData[this.currentDomain];if(!domainData){this.displayNotice("deleted");return}const status=domainData.dev_licence_status;switch(status){case"development":this.displayNotice("development",domainData);break;case"maintenance":this.displayNotice("maintenance",domainData);break;case"suspended":this.displayNotice("suspended",domainData);break;case"legal_hold":this.displayNotice("legal_hold",domainData);break;case"deleted":this.displayBlankPage();break;case"active":break;default:this.displayNotice("suspended",domainData)}}displayNotice(type,domainData=null){const notices={development:{title:"Exciting Changes Coming Soon!",message:"We're currently working behind the scenes to bring you a more robust, interactive, and modern website experience. Please check back soon for our exciting new launch!",color:"#4a6fa5",icon:"🚀",gradient:"linear-gradient(135deg, #e6f0ff 0%, #c9e2ff 100%)",contactLabel:"For inquiries, please contact:"},maintenance:{title:"Maintenance Ongoing",message:"We're currently performing important updates to improve your experience. Our team is working to complete this as quickly as possible. Thank you for your patience!",color:"#5a8f69",icon:"🔧",gradient:"linear-gradient(135deg, #f0fff4 0%, #d1ffe1 100%)",contactLabel:"Need immediate assistance?"},suspended:{title:"Service Unavailable",message:"This website is currently inaccessible due to administrative reasons.",color:"#a04a4a",icon:"⚠️",gradient:"linear-gradient(135deg, #fff0f0 0%, #ffd1d1 100%)",contactLabel:"For support inquiries:"},legal_hold:{title:"Access Restricted",message:"This website is temporarily unavailable due to legal proceedings.",color:"#6a4a8f",icon:"⚖️",gradient:"linear-gradient(135deg, #f5f0ff 0%, #e2d1ff 100%)",contactLabel:"Legal inquiries:"},deleted:{title:"Website Not Available",message:"This website is no longer active.",color:"#5a5a5a",icon:"❌",gradient:"linear-gradient(135deg, #f5f5f5 0%, #e0e0e0 100%)",contactLabel:""}};const notice=notices[type]||notices.suspended;const clientEmail=domainData?.customer_email||domainData?.client_email||"info@example.com";const clientName=domainData?.client_name||"the website owner";const clientPhone=domainData?.customer_phone?`<p>Phone: ${domainData.customer_phone}</p>`:"";const noticeHTML=`\n              <style>\n                  body {\n                      margin: 0;\n                      padding: 0;\n                      background: ${notice.gradient};\n                      font-family: 'Ubuntu', 'Segoe UI', Roboto, sans-serif;\n                      display: flex;\n                      justify-content: center;\n                      align-items: center;\n                      min-height: 100vh;\n                      color: #333;\n                      line-height: 1.5;\n                  }\n                  \n                  .license-notice {\n                      background: white;\n                      width: calc(100% - 40px);\n                      max-width: 500px;\n                      border-radius: 12px;\n                      box-shadow: 0 5px 15px rgba(0,0,0,0.08);\n                      padding: 1.5rem;\n                      margin: 20px;\n                      text-align: center;\n                      animation: fadeIn 0.4s ease-out;\n                      border: 1px solid rgba(0,0,0,0.05);\n                  }\n                  \n                  .notice-title {\n                      color: ${notice.color};\n                      font-weight: 700;\n                      font-size: 1.4rem;\n                      margin-bottom: 1rem;\n                      display: flex;\n                      align-items: center;\n                      justify-content: center;\n                      gap: 0.5rem;\n                  }\n                  \n                  .notice-content {\n                      color: #444;\n                      font-size: 1rem;\n                      margin-bottom: 1rem;\n                  }\n                  \n                  .divider {\n                      height: 1px;\n                      background: linear-gradient(90deg, transparent, ${notice.color}, transparent);\n                      margin: 1.5rem auto;\n                      width: 80%;\n                      opacity: 0.3;\n                  }\n                  \n                  .support-info {\n                      background: rgba(0,0,0,0.02);\n                      padding: 1rem;\n                      border-radius: 8px;\n                      margin: 1.5rem 0;\n                      border-left: 3px solid ${notice.color};\n                      text-align: left;\n                  }\n                  \n                  .support-link {\n                      color: ${notice.color};\n                      text-decoration: none;\n                      font-weight: 600;\n                      word-break: break-all;\n                      display: inline-block;\n                      margin-top: 0.3rem;\n                  }\n                  \n                  .client-info {\n                      font-size: 0.85rem;\n                      margin-top: 1rem;\n                      color: #666;\n                  }\n                  \n                  .icon {\n                      font-size: 1.3em;\n                  }\n                  \n                  @keyframes fadeIn {\n                      from { opacity: 0; transform: translateY(20px); }\n                      to { opacity: 1; transform: translateY(0); }\n                  }\n                  \n                  @media (max-width: 350px) {\n                      .license-notice {\n                          padding: 1.2rem;\n                          margin: 10px;\n                      }\n                      \n                      .notice-title {\n                          font-size: 1.2rem;\n                      }\n                  }\n              </style>\n              \n              <div class="license-notice">\n                  <h2 class="notice-title">\n                      <span class="icon">${notice.icon}</span>\n                      ${notice.title}\n                  </h2>\n                  \n                  <div class="notice-content">\n                      <p>${notice.message}</p>\n                  </div>\n                  \n                  ${type!=="deleted"?`\n                  <div class="divider"></div>\n                  \n                  <div class="support-info">\n                      <p style="margin:0 0 5px 0;font-weight:500;">${notice.contactLabel}</p>\n                      <a class="support-link" href="mailto:${clientEmail}">\n                          ${clientEmail}\n                      </a>\n                      ${clientPhone}\n                  </div>\n                  `:""}\n                  \n                  ${domainData?`\n                  <div class="client-info">\n                      <p>${clientName}</p>\n                  </div>\n                  `:""}\n              </div>\n          `;const container=document.createElement("div");container.innerHTML=noticeHTML;this.body.innerHTML="";this.body.appendChild(container)}displayBlankPage(){this.body.innerHTML="";this.body.style.backgroundColor="white";this.body.style.margin="0";this.body.style.padding="0";this.body.style.minHeight="100vh"}init(){this.fetchClientData()}}(new UbuntuDevSpace).init()}));